/** @param {NS} ns */
export async function main(ns) {
  const openPorts = [ns.brutessh, ns.ftpcrack, ns.relaysmtp, ns.httpworm, ns.sqlinject];
  const visited = new Set();
  const queue = ['home'];
  const servers = [];

  // BFS to find all reachable servers
  while (queue.length > 0) {
    const curr = queue.shift();
    if (visited.has(curr)) continue;
    visited.add(curr);
    servers.push(curr);

    const neighbors = ns.scan(curr);
    for (const neighbor of neighbors) {
      if (!visited.has(neighbor)) queue.push(neighbor);
    }
  }

  // Gain root access on all servers
  for (const server of servers) {
    if (ns.hasRootAccess(server)) continue;

    let portCount = 0;
    for (const openPort of openPorts) {
      try {
        if (ns.fileExists(openPort.name.split('.')[0] + '.exe', 'home')) {
          openPort(server);
          portCount++;
        }
      } catch (e) {}
    }

    if (portCount >= ns.getServerNumPortsRequired(server)) {
      ns.nuke(server);
    }
  }

  // Main hacking loop
  while (true) {
    let bestServer = 'n00dles';
    let bestMoney = 0;
    const myHackLevel = ns.getHackingLevel();

    // Find best server to hack
    for (const server of servers) {
      if (!ns.hasRootAccess(server)) continue;
      const reqLevel = ns.getServerRequiredHackingLevel(server);
      if (reqLevel > myHackLevel) continue;
      const maxMoney = ns.getServerMaxMoney(server);
      if (maxMoney > bestMoney) {
        bestMoney = maxMoney;
        bestServer = server;
      }
    }

    const security = ns.getServerSecurityLevel(bestServer);
    const minSecurity = ns.getServerMinSecurityLevel(bestServer);
    const money = ns.getServerMoneyAvailable(bestServer);
    const maxMoney = ns.getServerMaxMoney(bestServer);

    if (security > minSecurity + 5) {
      await ns.weaken(bestServer);
    } else if (money < maxMoney * 0.75) {
      await ns.grow(bestServer);
    } else {
      await ns.hack(bestServer);
    }
  }
}

